def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    chars = sorted(set(alphabet))

    children = [{}]
    out = [False]
    fail = [0]

    for s in banned:
        u = 0
        for ch in s:
            v = children[u].get(ch)
            if v is None:
                v = len(children)
                children[u][ch] = v
                children.append({})
                out.append(False)
                fail.append(0)
            u = v
        out[u] = True

    q = []
    for v in children[0].values():
        q.append(v)

    head = 0
    while head < len(q):
        u = q[head]
        head += 1
        for c, v in children[u].items():
            f = fail[u]
            while f != 0 and c not in children[f]:
                f = fail[f]
            if c in children[f]:
                fail[v] = children[f][c]
            else:
                fail[v] = 0
            q.append(v)

    bad = [None] * len(children)

    def is_bad(u: int) -> bool:
        if bad[u] is None:
            bad[u] = out[u] or (u != 0 and is_bad(fail[u]))
        return bad[u]

    for i in range(len(children)):
        is_bad(i)

    go_memo = {}

    def go(u: int, c: str) -> int:
        key = (u, c)
        res = go_memo.get(key)
        if res is None:
            if c in children[u]:
                res = children[u][c]
            elif u == 0:
                res = 0
            else:
                res = go(fail[u], c)
            go_memo[key] = res
        return res

    good = [i for i in range(len(children)) if not bad[i]]
    idx = {u: i for i, u in enumerate(good)}
    S = len(good)

    A = [[0] * S for _ in range(S)]
    for u in good:
        fu = idx[u]
        for c in chars:
            v = go(u, c)
            if not bad[v]:
                A[idx[v]][fu] = (A[idx[v]][fu] + 1) % MOD

    def mat_mul(X, Y):
        S = len(X)
        Z = [[0] * S for _ in range(S)]
        for i in range(S):
            Zi = Z[i]
            Xi = X[i]
            for k in range(S):
                a = Xi[k]
                if a:
                    Yk = Y[k]
                    for j in range(S):
                        Zi[j] = (Zi[j] + a * Yk[j]) % MOD
        return Z

    def mat_pow(M, e):
        S = len(M)
        R = [[int(i == j) for j in range(S)] for i in range(S)]
        B = [row[:] for row in M]
        while e:
            if e & 1:
                R = mat_mul(R, B)
            e >>= 1
            if e:
                B = mat_mul(B, B)
        return R

    P = mat_pow(A, n)
    r = idx[0]
    return sum(P[i][r] for i in range(S)) % MOD
